            result = f"{clean_sql} WHERE {tenant_condition}"
            if has_semicolon:
                result += ";"
            return result

    def _handle_delete_query(self, sql: str, sql_upper: str, tenant_condition: str) -> str:
        where_match = re.search(r'\bWHERE\b', sql_upper)
